/**
 * graph-extraction promptfoo output vs committed snapshot parity test.
 *
 * The committed snapshot (`evals/promptfoo/snapshots/graph-extraction-smoke.json`)
 * was generated by running the graph-extraction bridge through the promptfoo
 * engine in dry-run (deterministic "unavailable" mode). This test re-runs the
 * same bridge + opts and asserts the per-case judgment (caseId + passed + mode
 * + F1/strength fields) reproduces the snapshot exactly — no native execution
 * code involved.
 */

import { readFileSync } from 'node:fs';

import { describe, expect, it } from 'vitest';

import { graphExtractionBridge } from '../graph-extraction/bridge.js';
import { runSuiteWithPromptfoo } from './runner.js';
import { getSnapshotSuiteConfigs, snapshotFilePath } from './scripts/generate-snapshots.js';
import { suiteSnapshotSchema } from './snapshots/snapshot-schema.js';

describe('graph-extraction promptfoo output matches committed snapshot', () => {
  it('reproduces the smoke snapshot per-case', async () => {
    const config = getSnapshotSuiteConfigs().find((c) => c.suiteId === 'graph-extraction');
    expect(config).toBeDefined();
    expect(config!.opts.tier).toBe('smoke');

    const { report, caseCount } = await runSuiteWithPromptfoo(graphExtractionBridge, config!.opts);
    const entries = config!.extract(report).sort((a, b) => a.caseId.localeCompare(b.caseId));

    const snapshot = suiteSnapshotSchema.parse(
      JSON.parse(readFileSync(snapshotFilePath('graph-extraction'), 'utf8')),
    );

    expect(snapshot.cases.length).toBeGreaterThan(0);
    expect(caseCount).toBe(snapshot.cases.length);
    expect(entries).toEqual(snapshot.cases);
  });
});
